const vm = require('node:vm');

// A stand-in for jest-environment-node: a VM context whose global has Node's, as Jest builds it.
class NodeEnvironment {
  constructor(config, context) {
    this.context = vm.createContext();
    this.global = vm.runInContext('this', this.context);
    Object.assign(this.global, { process, setTimeout, clearTimeout, console: context.console });
  }

  async setup() {}

  async teardown() {
    this.context = null;
  }

  getVmContext() {
    return this.context;
  }
}

module.exports = NodeEnvironment;
module.exports.default = NodeEnvironment;
module.exports.TestEnvironment = NodeEnvironment;
